// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(uint256 amount) public {
        // Admissible domain: the contract carries a strictly positive balance before destruction.
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);

        // The owner of c is this test contract (its deployer); drive c through sudicideAnyone.
        c.sudicideAnyone();

        // General rule: destroying c pays its entire balance to the CALLER (the owner),
        // so no funds ever land on the zero address.
        // Reference C: balance of address(0) remains 0 for every admissible amount.
        // Mutant M: sends amount to address(0), so its balance becomes amount > 0.
        assertTrue(address(0).balance == 0);
    }
}
